parameters.jsCode:
// Verify HMAC-SHA256 signature from Convex.
// Convex signs the exact JSON body with N8N_WEBHOOK_SECRET and sends it as
// the `x-lendloop-signature` header. The webhook node is configured with
// rawBody=true, so $json.body holds the payload; JSON.stringify restores the
// canonical signed bytes for our payload shape (key order is stable).
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
const out = [];
for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const provided = headers['x-lendloop-signature'] || '';
  const raw = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body ?? {});
  const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
  const valid = provided.length === expected.length && crypto.timingSafeEqual(Buffer.from(provided), Buffer.from(expected));
  const payload = typeof item.json.body === 'string' ? JSON.parse(item.json.body) : item.json.body;
  out.push({ json: { signatureValid: valid, event: payload.event, loan: payload.loan, occurredAt: payload.occurredAt } });
}
return out;

// SAFE DEFAULT notification channel: log a mock notification.
// To send real email, disable this node and enable 'Send Email (disabled)'
// after configuring a genuine SMTP credential on it.
const out = [];
for (const item of $input.all()) {
  const loan = item.json.loan || {};
  const message = `[LendLoop mock notification] ${item.json.event}: "${loan.toolName}" requested by ${loan.borrowerName}, ${loan.startDate} to ${loan.endDate}, status=${loan.status}. (No real email sent; enable the email node with a real credential to go live.)`;
  console.log(message);
  out.push({ json: { notified: true, channel: 'mock-log', event: item.json.event, loanId: loan.id, message } });
}
return out;

